"use strict";
// Markdown generated by an AI is untrusted. Raw HTML is escaped; links have an explicit protocol allowlist.
const AIHubMarkdown = (() => {
  const escape = (text) => String(text).replace(/[&<>"']/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const safeUrl = (url) => /^(https?:\/\/|mailto:|#)/i.test(url.trim()) && !/[\u0000-\u0020]/.test(url);
  function inline(text) {
    const held = [];
    const keep = (html) => `\u0000${held.push(html) - 1}\u0000`;
    let source = String(text).replace(/\u0000/g, "�");
    source = source.replace(/`([^`\n]+)`/g, (_, code) => keep(`<code>${escape(code)}</code>`));
    source = source.replace(/\[([^\]\n]+)\]\(([^\s)]+)\)/g, (all, label, url) => safeUrl(url)
      ? keep(`<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(label)}</a>`) : all);
    source = escape(source).replace(/\*\*([^*\n]+)\*\*/g, "<strong>$1</strong>")
      .replace(/~~([^~\n]+)~~/g, "<del>$1</del>")
      .replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g, "$1<em>$2</em>");
    return source.replace(/\u0000(\d+)\u0000/g, (_, n) => held[Number(n)]);
  }
  const cells = (line) => line.trim().replace(/^\|/, "").replace(/\|$/, "").split(/(?<!\\)\|/).map((c) => c.trim());
  const list = (line) => line.match(/^(\s*)([-+*]|\d+[.)])\s+(.+)$/);
  const separator = (line) => cells(line).every((cell) => /^:?-{3,}:?$/.test(cell));
  function render(text, depth = 0) {
    if (depth > 24) return `<pre>${escape(text)}</pre>`;
    const lines = String(text || "").replace(/\r\n?/g, "\n").split("\n");
    const output = [];
    let i = 0;
    const startsBlock = (at) => /^\s*(```|~~~|#{1,6}\s|>|[-*_]{3,}\s*$)/.test(lines[at] || "") ||
      Boolean(list(lines[at] || "")) || (at + 1 < lines.length && lines[at].includes("|") && separator(lines[at + 1]));
    function items(indent, nested = 0) {
      const first = list(lines[i]);
      const ordered = /^\d/.test(first[2]);
      const tag = ordered ? "ol" : "ul";
      let html = `<${tag}${ordered ? ` start="${parseInt(first[2], 10)}"` : ""}>`;
      while (i < lines.length) {
        const item = list(lines[i]);
        if (!item || item[1].length !== indent || /^\d/.test(item[2]) !== ordered) break;
        let content = item[3];
        content = content.replace(/^\[([ xX])\]\s*/, (_, checked) => checked.trim() ? "☑ " : "☐ ");
        html += `<li>${inline(content)}`;
        i++;
        while (i < lines.length && list(lines[i]) && list(lines[i])[1].length > indent) {
          if (nested > 24) { html += inline(lines[i++]); continue; }
          html += items(list(lines[i])[1].length, nested + 1);
        }
        html += "</li>";
      }
      return html + `</${tag}>`;
    }
    while (i < lines.length) {
      const line = lines[i];
      if (!line.trim()) { i++; continue; }
      const fence = line.match(/^\s*(`{3,}|~{3,})([\w+-]*)\s*$/);
      if (fence) {
        const code = [];
        i++;
        while (i < lines.length && !lines[i].trim().startsWith(fence[1])) code.push(lines[i++]);
        if (i < lines.length) i++;
        output.push(`<div class="code-block"><button type="button" class="code-copy">Copier le code</button>` +
          `<pre><code${fence[2] ? ` class="language-${escape(fence[2])}"` : ""}>${escape(code.join("\n"))}</code></pre></div>`);
        continue;
      }
      const heading = line.match(/^(#{1,6})\s+(.+?)\s*#*$/);
      if (heading) { output.push(`<h${heading[1].length}>${inline(heading[2])}</h${heading[1].length}>`); i++; continue; }
      if (/^\s*(\*\s*){3,}$|^\s*(-\s*){3,}$|^\s*(_\s*){3,}$/.test(line)) { output.push("<hr>"); i++; continue; }
      if (/^\s*>/.test(line)) {
        const quote = [];
        while (i < lines.length && /^\s*>/.test(lines[i])) quote.push(lines[i++].replace(/^\s*>\s?/, ""));
        output.push(`<blockquote>${render(quote.join("\n"), depth + 1)}</blockquote>`);
        continue;
      }
      if (i + 1 < lines.length && line.includes("|") && separator(lines[i + 1])) {
        const headings = cells(line), rules = cells(lines[i + 1]);
        const cls = (n) => rules[n]?.endsWith(":") ? (rules[n].startsWith(":") ? "center" : "right") : "left";
        i += 2;
        let table = '<div class="table-scroll"><table><thead><tr>' + headings.map((cell, n) =>
          `<th class="align-${cls(n)}">${inline(cell)}</th>`).join("") + "</tr></thead><tbody>";
        while (i < lines.length && lines[i].trim() && lines[i].includes("|")) {
          const row = cells(lines[i++]);
          table += "<tr>" + headings.map((_, n) => `<td class="align-${cls(n)}">${inline(row[n] || "")}</td>`).join("") + "</tr>";
        }
        output.push(table + "</tbody></table></div>");
        continue;
      }
      if (list(line)) { output.push(items(list(line)[1].length)); continue; }
      const paragraph = [line];
      i++;
      while (i < lines.length && lines[i].trim() && !startsBlock(i)) paragraph.push(lines[i++]);
      output.push(`<p>${paragraph.map(inline).join("<br>")}</p>`);
    }
    return output.join("");
  }
  return { render };
})();
if (typeof module !== "undefined") module.exports = AIHubMarkdown;
